"""Tax helpers."""

RATES = {"RO": 0.19, "DE": 0.19, "HU": 0.27}


def calculate_tax(amount: float, region: str) -> float:
    """Return the VAT due for amount in the given region."""
    return round(amount * RATES[region], 2)

